effect.shader:
// O mesmo `oitoBits`, `fundoPre` e `fundoNoPonto` da atual (ver `am-displacement-map.xml`).
float oitoBits(float k) {
    uint n = uint(k);
    if (n == 0u) return 0.0;
    if (n == 255u) return 1.0;
    int j = 0;
    for (int i = 1; i < 8; i++) if (n >= (1u << uint(i))) j = i;
    int e = 31 - j;
    uint q = ((n << uint(e)) + 127u) / 255u;
    return uintBitsToFloat((uint(150 - e) << 23) + (q - 0x800000u));
}

vec4 fundoPre(ivec2 px) {
    vec4 c = texelFetch(comp, px, 0);
    if (c.a >= 1.0) return c;
    vec3 k = floor(c.rgb * c.a * 255.0 + 0.5);
    return vec4(oitoBits(k.r), oitoBits(k.g), oitoBits(k.b), c.a);
}

vec4 fundoNoPonto(vec2 uv) {
    vec4 g = texture(comp, uv);
    if (g.a >= 1.0) return g;
    ivec2 T = textureSize(comp, 0);
    vec2 p = uv * vec2(T) - 0.5;
    vec2 i = floor(p);
    vec2 f = p - i;
    ivec2 a = ivec2(i);
    ivec2 m = T - 1;
    vec4 c00 = fundoPre(clamp(a, ivec2(0), m));
    vec4 c10 = fundoPre(clamp(a + ivec2(1, 0), ivec2(0), m));
    vec4 c01 = fundoPre(clamp(a + ivec2(0, 1), ivec2(0), m));
    vec4 c11 = fundoPre(clamp(a + ivec2(1, 1), ivec2(0), m));
    return mix(mix(c00, c10, f.x), mix(c01, c11, f.x), f.y);
}

void main() {
    vec2 tela = acTela(acScreenNorm);

    vec2 adjOffs = offs / 1000.0;
    adjOffs.x *= acTamanhoDaCamada.x/acTamanhoDaCamada.y * -1.0;

    vec4 texColor = texture(inputImg, acScreenNorm);
    if (texColor.a < 1.0) {
        vec3 k = floor(texColor.rgb * texColor.a * 255.0 + 0.5);
        texColor.rgb = vec3(oitoBits(k.r), oitoBits(k.g), oitoBits(k.b));
    }
    float p = 0.0;
    if( type==0 ) {
        p = texColor.r*0.2126 + texColor.g*0.7152 + texColor.b*0.0722;
    } else if( type == 1 ) {
        p = texColor.r;
    } else if( type == 2 ) {
        p = texColor.g;
    } else if( type == 3 ) {
        p = texColor.b;
    } else {
        adjOffs *= 0.0;
    }
    if( fromctr ) {
        p = (p-0.5)*2.0;
    }
    if( invert ) {
        adjOffs *= (1.0-p) * texColor.a;
    } else {
        adjOffs *= p * texColor.a;
    }

    vec2 amostra = tela + adjOffs;
    vec4 saida;
    if(edges==0) {
        saida = fundoNoPonto(amostra);
    } else if(edges==1) {
        amostra = vec2(1.0,1.0) - abs(mod(amostra,vec2(2.0,2.0))-vec2(1.0,1.0));
        saida = fundoNoPonto(amostra) * texColor.a;
    } else if(edges==2) {
        if( amostra.x < 0.0 || amostra.x > 1.0 || amostra.y < 0.0 || amostra.y > 1.0 ) {
            saida = vec4(0.0,0.0,0.0,0.0);
        } else {
            saida = fundoNoPonto(amostra) * texColor.a;
        }
    } else if(edges==3) {
        amostra = mod(amostra,vec2(1.0,1.0));
        saida = fundoNoPonto(amostra) * texColor.a;
    } else {
        saida = fundoNoPonto(amostra) * texColor.a;
    }

    fragColor = saida.a > 0.0 ? vec4(saida.rgb / saida.a, saida.a) : vec4(0.0);
}
